const inp = $input.first().json;
const raw = inp.body || {};
const hdr = inp.headers || {};
const sd = $getWorkflowStaticData('global');

// 1) 입력 형식 통일: Graylog 표준 본문(schema 1.1: rule/alert/event) 또는 이전의 평평한 형식을 모두 받습니다
const isEnv = !!(raw.rule && raw.event);
const ev = raw.event || {};
const ex = ev.evidence || {};
const clean = v => (v === '-' || v == null) ? '' : String(v);
const PRIO = { 1: 'info', 2: 'low', 3: 'medium', 4: 'high', 5: 'critical' };
const b = isEnv ? {
  rule_id: raw.rule.id,
  rule_name: String(raw.rule.display_name || (raw.alert && raw.alert.title) || '').replace(/^\[NEXUS\]\[R\d+\]\s*/, ''),
  severity: ev.severity || PRIO[raw.alert && raw.alert.priority] || 'medium',
  src_ip: clean(ev.src_ip),
  user: clean(ev.user),
  count: ex.event_count ?? ex.failed_attempts ?? ex.denied_calls ?? ex.retry_count ?? ex.distinct_users ?? 1,
  first_seen: raw.alert && raw.alert.timestamp,
  last_seen: raw.alert && raw.alert.timestamp,
  graylog_event_id: (raw.alert && raw.alert.id) || '',
} : { ...raw, src_ip: clean(raw.src_ip), user: clean(raw.user) };
const lvl = String(raw.action_level || '').toLowerCase();
const dec = String(ev.decision || '').toUpperCase();

// 2) 중복 방지: 같은 alert.id는 한 번만 처리합니다 (최근 500개 기억)
sd.seen = sd.seen || {};
if (b.graylog_event_id) {
  if (sd.seen[b.graylog_event_id]) { sd.dups = (sd.dups || 0) + 1; return []; }
  sd.seen[b.graylog_event_id] = Date.now();
  const ks = Object.keys(sd.seen);
  if (ks.length > 500) for (const k of ks.sort((x, y) => sd.seen[x] - sd.seen[y]).slice(0, ks.length - 500)) delete sd.seen[k];
}

// 3) 규칙별 대응 계획 (R1~R12). group은 아래 '규칙별 대응' 분기 기준
const T = { alert: '이상 징후 경보', block: '차단 조치', inc: '침해 인시던트' };
const NOTIFY = { g: 'notify', a: [], t: T.alert };
const SESSION_AI = { g: 'session_ai', a: ['세션 종료', 'AI Tool 제한'], t: T.inc };
const PLAN = {
  R1: { g: 'lock', a: ['계정 잠금'], t: T.block },
  R2: NOTIFY,
  R3: SESSION_AI,
  R4: { g: 'token', a: ['내부 API 토큰 폐기'], t: T.inc },
  R5: NOTIFY, R6: NOTIFY, R7: NOTIFY, R8: NOTIFY, R9: NOTIFY, R10: NOTIFY,
  R11: SESSION_AI, R12: SESSION_AI,
};
let p = PLAN[b.rule_id] || { g: 'notify', a: [], t: lvl === 'contain' ? T.block : T.alert };
// R4: 방어 후 DENY는 이미 막힌 호출이므로 토큰 폐기 없이 알림·티켓(차단 조치)만
if (b.rule_id === 'R4' && dec === 'DENY') p = { g: 'notify', a: [], t: T.block };
const observe = lvl === 'observe';   // 관찰용 규칙(R7)은 Discord 없이 티켓만 남깁니다
const actions = [...p.a, ...(observe ? [] : ['Discord 알림']), '티켓 생성'];

const bits = [`[${b.rule_id}] ${b.rule_name}`, `출발지 ${b.src_ip || '-'}`, `계정 ${b.user || '-'}`, `${b.count}건`];
if (dec) bits.push('판정 ' + dec);
if (ev.tool_name) bits.push('Tool ' + ev.tool_name);
if (b.rule_id === 'R4' && dec) bits.push(dec === 'ALLOW' ? '방어 전 성공' : '방어 후 차단');
bits.push('대응 예정: ' + actions.join(', '));

return [{ json: {
  rule_id: b.rule_id, rule_name: b.rule_name, severity: b.severity,
  src_ip: b.src_ip, user: b.user, count: b.count,
  first_seen: b.first_seen, last_seen: b.last_seen,
  graylog_event_id: b.graylog_event_id,
  action_level: lvl, decision: dec, tool_name: ev.tool_name || '', request_id: ev.request_id || '',
  session_id: ev.session_id || '', caller_service: ev.caller_service || '',
  ticket_type: p.t, ticket_key: b.src_ip || (b.user ? 'user:' + b.user : 'unknown'),   // 출발지 IP가 없으면 계정 기준
  response_group: p.g, actions, message: bits.join(' | '),
  discord_enabled: !!$env.DISCORD_WEBHOOK_URL && !observe && hdr['x-dry-run'] !== '1',
  // 대응 실행 방식: 요청 헤더 X-Response-Mode 가 우선, 시험 헤더(X-Dry-Run)가 있으면 dry-run, 아니면 환경변수(RESPONSE_MODE, 기본 dry-run)
  response_mode: ['live', 'dry-run'].includes(String(hdr['x-response-mode'] || '')) ? String(hdr['x-response-mode']) : (hdr['x-dry-run'] === '1' ? 'dry-run' : ($env.RESPONSE_MODE === 'live' ? 'live' : 'dry-run')),
} }];

const d = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.tickets = sd.tickets || {};
sd.history = sd.history || [];
sd.whitelist = sd.whitelist || {};
sd.skipped = sd.skipped || [];
sd.seq = sd.seq || 0;
// 화이트리스트(정상 IP)는 티켓·대응 없이 건너뜁니다 (환경변수 WHITELIST_IPS + 상황판에서 추가한 IP)
const envWl = String($env.WHITELIST_IPS || '').split(',').map(s => s.trim()).filter(Boolean);
if (d.src_ip && (envWl.includes(d.src_ip) || sd.whitelist[d.src_ip])) {
  sd.skipped.unshift({ time: d.last_seen, src_ip: d.src_ip, rule_id: d.rule_id });
  sd.skipped = sd.skipped.slice(0, 50);
  return [];
}
const rank = { '이상 징후 경보': 1, '차단 조치': 2, '침해 인시던트': 3 };
const key = d.ticket_key;                       // 공격 팀(출발지 IP)별로 티켓을 나눕니다
let t = sd.tickets[key];
let isNew = false;
if (t && t.status === 'closed') { sd.history.push(t); t = null; }   // 종료된 티켓은 기록으로 보관
if (!t) {
  sd.seq += 1;
  t = { id: 'NX-' + String(sd.seq).padStart(4, '0'), src_ip: key, type: d.ticket_type,
        rules: [], users: [], count: 0, first_seen: d.first_seen, last_seen: d.last_seen, status: 'open', stage: '접수', severity: d.severity, signals: [] };
  isNew = true;
}
const SEV = { info: 1, low: 2, medium: 3, high: 4, critical: 5 };
t.stage = t.stage || '접수'; t.severity = t.severity || d.severity;   // 이전에 만들어진 티켓 보강
const wasAlert = t.type === '이상 징후 경보';
if ((rank[d.ticket_type] || 0) > (rank[t.type] || 0)) t.type = d.ticket_type;   // 더 심각한 유형으로 올림
if (!isNew && wasAlert && t.type !== '이상 징후 경보') t.stage = '승격';            // 경보 → 차단 조치·침해 인시던트
else if (!isNew && t.type === '이상 징후 경보' && t.stage === '접수') t.stage = '모니터링';
if ((SEV[d.severity] || 0) > (SEV[t.severity] || 0)) t.severity = d.severity;      // 심각도는 가장 높은 값
t.signals = t.signals || [];
if (!t.signals.some(s => s.rule_id === d.rule_id)) t.signals.push({ rule_id: d.rule_id, rule_name: d.rule_name });
if (!t.rules.includes(d.rule_id)) t.rules.push(d.rule_id);
if (d.user && !t.users.includes(d.user)) t.users.push(d.user);
t.count += Number(d.count) || 1;
t.last_seen = d.last_seen;
sd.tickets[key] = t;
return [{ json: { ...d,
  ticket_id: t.id, ticket_is_new: isNew, ticket_type: t.type,
  ticket_rules: t.rules, ticket_users: t.users, ticket_event_total: t.count,
  message: `[${t.id} ${isNew ? '신규' : '갱신'}] ` + d.message } }];

const tok = $env.WEBHOOK_TOKEN;
const h = $input.first().json.headers || {};
if (!tok || h['x-webhook-token'] !== tok) return [{ json: { http: 401, body: { status: 'unauthorized' } } }];
const sd = $getWorkflowStaticData('global');
sd.tickets = sd.tickets || {}; sd.history = sd.history || []; sd.whitelist = sd.whitelist || {}; sd.skipped = sd.skipped || [];
const envWl = String($env.WHITELIST_IPS || '').split(',').map(s => s.trim()).filter(Boolean);
const all = [...Object.values(sd.tickets), ...sd.history].sort((a, b) => (a.id < b.id ? 1 : -1));
const open = all.filter(t => t.status === 'open');
const by_type = {};
for (const t of open) by_type[t.type] = (by_type[t.type] || 0) + 1;
return [{ json: { http: 200, body: {
  generated_at: new Date().toISOString(),
  summary: { open: open.length, closed: all.length - open.length, by_type },
  tickets: all,
  whitelist: [...envWl.map(ip => ({ ip, source: '환경설정' })), ...Object.entries(sd.whitelist).map(([ip, v]) => ({ ip, source: '상황판', ...v }))],
  skipped: sd.skipped.slice(0, 10),
} } }];

const tok = $env.WEBHOOK_TOKEN;
const h = $input.first().json.headers || {};
if (!tok || h['x-webhook-token'] !== tok) return [{ json: { http: 401, body: { status: 'unauthorized' } } }];
const sd = $getWorkflowStaticData('global');
sd.tickets = sd.tickets || {}; sd.history = sd.history || []; sd.whitelist = sd.whitelist || {}; sd.skipped = sd.skipped || [];
const envWl = String($env.WHITELIST_IPS || '').split(',').map(s => s.trim()).filter(Boolean);
const b = $input.first().json.body || {};
const now = new Date().toISOString();
const ipOk = ip => /^(\d{1,3}\.){3}\d{1,3}$/.test(String(ip || ''));
const res = (http, body) => [{ json: { http, body } }];
const userOk = u => /^[A-Za-z][A-Za-z0-9._-]{0,49}$/.test(String(u || ''));
const findT = id => Object.values(sd.tickets).find(x => x.id === id);
const mode = String(h['x-response-mode'] || $env.RESPONSE_MODE || 'dry-run').toLowerCase() === 'live' ? 'live' : 'dry-run';
const lockMin = Math.min(Math.max(parseInt($env.LOCK_MINUTES || '15', 10) || 15, 1), 1440);
const LABEL = { applied: '적용', no_change: '변경 없음', 'dry-run': '미실행(dry-run)', error: '오류' };
const addRec = (t, rec) => { t.responses = (t.responses || []).concat([rec]).slice(-30); };
if (b.action === 'close' || b.action === 'false_positive') {
  const t = Object.values(sd.tickets).find(x => x.id === b.ticket_id);
  if (!t) return res(404, { status: 'not_found' });
  if (t.status === 'closed') return res(409, { status: 'already_closed' });
  t.status = 'closed';
  t.stage = '종료';
  t.resolution = b.action === 'false_positive' ? '오탐' : '조치 완료';
  t.closed_at = now;
  t.note = String(b.note || '').slice(0, 500);
  if (b.action === 'false_positive' && b.whitelist === true && ipOk(t.src_ip)) sd.whitelist[t.src_ip] = { added_at: now, reason: '오탐 ' + t.id };
  return res(200, { status: 'ok', ticket: t });
}
if (b.action === 'request_release') {            // 4번째 티켓 유형: 오탐·해제 요청
  const user = String(b.user || '').trim();
  if (!userOk(user)) return res(400, { status: 'bad_user' });
  const linked = b.ticket_id ? findT(b.ticket_id) : null;
  if (b.ticket_id && !linked) return res(404, { status: 'not_found' });
  sd.seq = (sd.seq || 0) + 1;
  const t = { id: 'NX-' + String(sd.seq).padStart(4, '0'), src_ip: linked ? linked.src_ip : '-', type: '오탐·해제 요청',
              rules: [], users: [user], user, count: 1, first_seen: now, last_seen: now, status: 'open', stage: '요청', severity: 'low', signals: [], approver: null,
              linked_ticket: linked ? linked.id : null, reason: String(b.reason || '').slice(0, 300) };
  sd.tickets['request:' + t.id] = t;
  return res(200, { status: 'ok', ticket: t });
}
if (b.action === 'release' || b.action === 'lock') {   // 잠금 해제 / 사람이 승인하는 잠금(고정 계정 포함)
  const t = findT(b.ticket_id);
  if (!t) return res(404, { status: 'not_found' });
  const user = String(b.user || t.user || (t.users.length === 1 ? t.users[0] : '')).trim();
  if (!userOk(user)) return res(400, { status: 'bad_user', hint: 'user 를 지정하세요' });
  if (![...(t.users || []), t.user].includes(user)) return res(400, { status: 'user_not_in_ticket' });
  const rel = b.action === 'release';
  const ctx = { ticket_id: t.id, user, kind: b.action, mode, by: '상황판',
    step: rel ? '계정 잠금 해제' : '계정 잠금(사람 승인)',
    undo: rel ? '상황판의 "잠금(승인)"으로 다시 잠금' : 'locked_until = NULL (잠금 해제)' };
  if (mode !== 'live') {
    const rec = { time: now, step: ctx.step, user, mode, status: 'dry-run', label: LABEL['dry-run'], by: ctx.by, detail: 'dry-run(DB를 바꾸지 않음)', undo: ctx.undo };
    addRec(t, rec);
    return res(200, { status: 'ok', result: rec, ticket: t });
  }
  const sql = rel ? 'UPDATE users SET locked_until = NULL WHERE username = $1'
                  : 'UPDATE users SET locked_until = DATE_ADD(NOW(), INTERVAL $1 MINUTE) WHERE username = $2';
  const verify = "SELECT '" + (rel ? 'release' : 'lock') + "' AS step_key, username, pinned, locked_until, (locked_until IS NOT NULL AND locked_until > NOW()) AS locked, session_version FROM users WHERE username = $1";
  return [{ json: { http: 200, body: null, db: { ...ctx, execute: true, sql, params: rel ? [user] : [lockMin, user], verify_sql: verify } } }];
}
if (b.action === 'whitelist_add') {
  if (!ipOk(b.ip)) return res(400, { status: 'bad_ip' });
  sd.whitelist[b.ip] = { added_at: now, reason: String(b.note || '수동 추가').slice(0, 200) };
  return res(200, { status: 'ok', ip: b.ip });
}
if (b.action === 'whitelist_remove') {
  if (!sd.whitelist[b.ip]) return res(404, { status: 'not_found' });
  delete sd.whitelist[b.ip];
  return res(200, { status: 'ok', ip: b.ip });
}
return res(400, { status: 'bad_action', allowed: ['close', 'false_positive', 'release', 'lock', 'request_release', 'whitelist_add', 'whitelist_remove'] });

const d = $input.first().json;
const live = d.response_mode === 'live';
const lockMin = Math.min(Math.max(parseInt($env.LOCK_MINUTES || '15', 10) || 15, 1), 1440);
const user = String(d.user || '').trim();
const okUser = /^[A-Za-z][A-Za-z0-9._-]{0,49}$/.test(user);   // 숫자로 시작하면 숫자로 해석될 수 있어 거부
const base = { ticket_id: d.ticket_id, ticket_key: d.ticket_key, rule_id: d.rule_id, user, mode: d.response_mode, discord_enabled: d.discord_enabled };
const steps = [];
// 보호 계정(시험·강사님 계정 등, .env 의 PROTECTED_USERS): 자동 잠금 대신 세션 종료만 하고 잠금은 사람이 상황판에서 승인합니다
const prot = String($env.PROTECTED_USERS || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const isProt = prot.includes(user.toLowerCase());
// 조치 뒤 읽기 전용 확인 조회(UPDATE 문은 결과 행 수를 돌려주지 않아 별도로 확인합니다)
const VERIFY = k => "SELECT '" + k + "' AS step_key, username, pinned, locked_until, (locked_until IS NOT NULL AND locked_until > NOW()) AS locked, session_version FROM users WHERE username = $1";
// SQL은 상수 문자열이고 값은 $1, $2 자리표시자로만 넣습니다(n8n MySQL 노드 방식).
if (d.response_group === 'lock' && isProt) {
  steps.push({ step: '세션 종료(보호 계정, 잠금은 사람 승인)', sql: 'UPDATE users SET session_version = session_version + 1 WHERE username = $1',
    params: [user], verify_sql: VERIFY('protected'), undo: '되돌릴 필요 없음(다시 로그인하면 됨). 잠금은 상황판에서 사람이 승인' });
} else if (d.response_group === 'lock') {
  // 일반 계정은 잠금, 고정(pinned) 계정은 잠금 없이 세션 종료만(잠금은 사람 승인). 시각은 DB 시계(NOW(), UTC)만 씁니다.
  steps.push({ step: '계정 잠금', sql: 'UPDATE users SET locked_until = IF(pinned = 0, DATE_ADD(NOW(), INTERVAL $1 MINUTE), locked_until), session_version = IF(pinned = 1, session_version + 1, session_version) WHERE username = $2',
    params: [lockMin, user], verify_sql: VERIFY('lock'), undo: 'UPDATE users SET locked_until = NULL WHERE username = ?', note: lockMin + '분' });
}
if (d.response_group === 'session_ai') {
  steps.push({ step: '세션 종료(강제 로그아웃)', sql: 'UPDATE users SET session_version = session_version + 1 WHERE username = $1',
    params: [user], verify_sql: VERIFY('logout'), undo: '되돌릴 필요 없음(다시 로그인하면 됨)' });
  steps.push({ step: 'AI Tool 제한', pending: 'AI 연동 단계에서 구현' });
}
return steps.map(s => ({ json: { ...base, ...s,
  execute: live && okUser && !!s.sql,
  skip_reason: !s.sql ? s.pending : (!okUser ? (user ? '계정 이름 형식 오류' : '대상 계정 없음') : (!live ? 'dry-run(DB를 바꾸지 않음)' : '')) } }));

const prep = $('대응 준비(DB 조치)').all();
const sd = $getWorkflowStaticData('global');
const LABEL = { applied: '적용', partial: '일부 적용(세션 종료만)', no_change: '변경 없음', 'dry-run': '미실행(dry-run)', skipped: '건너뜀', error: '오류', pending: 'AI 연동 후 구현' };
let updErr = null;
try { updErr = $('DB 조치 실행').all().find(u => u.json && u.json.error) || null; } catch (e) {}
const execCtx = (prep.find(p => p.json.execute) || {}).json;
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  let ctx, status, detail = '', note;
  if (j.step) {                                   // DB를 거치지 않은 항목(dry-run·건너뜀·보류)
    ctx = j; detail = j.skip_reason || '';
    status = j.pending ? 'pending' : (String(j.skip_reason).startsWith('dry-run') ? 'dry-run' : 'skipped');
  } else {                                        // 조치 후 확인 조회 결과
    ctx = execCtx || {};
    if (updErr || j.error) { status = 'error'; detail = String((updErr ? updErr.json.message : j.message) || '').slice(0, 200); }
    else if (!j.username) { status = 'no_change'; detail = '대상 계정을 찾지 못함'; }
    else if (j.step_key === 'protected') { status = 'partial'; detail = '보호 계정: 잠금 없이 세션 종료만 실행. 잠금은 사람이 승인'; note = '세션 버전 ' + j.session_version; }
    else if (Number(j.pinned) === 1 && j.step_key === 'lock') { status = 'partial'; detail = '고정 계정: 잠금 없이 세션 종료만 실행. 잠금은 사람이 승인'; note = '세션 버전 ' + j.session_version; }
    else if (j.step_key === 'lock' && !Number(j.locked)) { status = 'error'; detail = '조치 후에도 잠금 상태가 아님'; }
    else { status = 'applied'; note = j.step_key === 'lock' ? ('잠금 해제 예정 ' + j.locked_until) : ('세션 버전 ' + j.session_version); }
  }
  const rec = { time: new Date().toISOString(), step: ctx.step, user: ctx.user, mode: ctx.mode, status, label: LABEL[status], by: 'n8n 자동' };
  if (detail) rec.detail = detail;
  if (note || ctx.note) rec.note = note || ctx.note;
  if (ctx.undo) rec.undo = ctx.undo;
  const t = sd.tickets && sd.tickets[ctx.ticket_key];
  if (t) {
    t.responses = (t.responses || []).concat([rec]).slice(-30);
    if (['applied', 'partial'].includes(status) && ['접수', '모니터링', '승격'].includes(t.stage)) t.stage = '조치 중';
  }
  out.push({ json: { ...rec, ticket_id: ctx.ticket_id, rule_id: ctx.rule_id,
    discord_enabled: !!ctx.discord_enabled && ['applied', 'partial', 'no_change', 'error'].includes(status),
    message: `[${ctx.ticket_id}] 대응 결과: ${ctx.step} → ${LABEL[status]} | 대상 ${ctx.user || '-'}` + (rec.note ? ' | ' + rec.note : '') + (detail ? ' | ' + detail : '') } });
}
return out;

const ctx = $('티켓 처리·화이트리스트').first().json.db;
